// (uncompressed public point): up to three valid cases of each flag set and
// every invalid uncompressed point.

template <size_t Size>
struct ecdh_vector
{
    size_t id;
    data_array<Size> secret;
    data_array<add1(two * Size)> point;
    data_array<Size> shared;
};

